@startuml

class OrganizationalUnit {}

class Division extends OrganizationalUnit {}

class Subdivision extends OrganizationalUnit {}

class Branch extends OrganizationalUnit {
  + address
  + number
}

class AccountType {
  + interestRate
  + monthlyFee
  + privileges
}

class Account {
  + accountNumber
  + balance
  + creditOrOverdraftLimit
}

class MortgageAccount extends Account {
  + collateralProperty
}

class CheckingAccount extends Account {}

class CreditCardAccount extends Account {
  + expiryDate
}

class Person {}

class Employee extends Person {}

class Customer extends Person {}

OrganizationalUnit "1" -- "*" Subdivision : contains
Division "1" -- "*" Division : contains
Division "1" -- "*" Employee : managed by
Division "1" -- "*" Employee : has
Subdivision "1" -- "*" Branch : contains
Subdivision "1" -- "*" Employee : has
Branch "1" -- "*" Account : offers
Branch "1" -- "*" Customer : serves
Customer "1" -- "*" Account : owns
Customer "1" -- "1" Employee : personalBanker
AccountType "1" -- "*" Account : defines
CreditCardAccount "1" -- "*" CreditCardAccount : secondary cards

@enduml

